.prose li { margin-block: 7px; }
.prose pre { overflow: auto; background: var(--af-paper) !important; border: 1px solid var(--af-line); border-radius: 8px; padding: 22px; font-size: 12.5px; line-height: 1.8; }
.prose .code-block pre { margin-block: 24px; }
.prose :not(pre) > code { background: var(--af-soft); padding: 2px 5px; border-radius: 4px; overflow-wrap: anywhere; }
.prose table { border-collapse: collapse; width: 100%; font-size: 14px; }
.prose th, .prose td { padding: 12px; text-align: left; border-bottom: 1px solid var(--af-line); }
.article-footer { margin-top: 48px; padding-top: 23px; border-top: 1px solid var(--af-line); }
.no-script-note { padding: 12px 20px; font-size: 13px; }
@media (prefers-reduced-motion: no-preference) {
  html { scroll-behavior: smooth; }
  .github-link:is(:hover, :focus-visible) .github-tail { animation: github-tail-wag 850ms ease-in-out infinite; }
  @keyframes github-tail-wag {
    0%, 100% { transform: rotate(0); }
    25%, 75% { transform: rotate(-14deg); }
    50% { transform: rotate(12deg); }
  }
  .flashcard-inner { transition: transform 420ms cubic-bezier(0.2, 0.65, 0.3, 1); }
  .example-panel:not([hidden]) { animation: panel-in 180ms ease-out; }
  .identity-fields .is-updated { animation: panel-in 220ms ease-out; }
  [data-reveal].is-revealed { animation: section-in 450ms ease-out; }
  @keyframes panel-in { from { opacity: 0.5; transform: translateY(3px); } to { opacity: 1; transform: translateY(0); } }
  @keyframes section-in { from { opacity: 0.65; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
}
@media (max-width: 1024px) {
  .hero-actions { gap: 17px; }
  .identity-section, .start-section { gap: 45px; }
  .card-preview { padding-inline: 23px; }
}
@media (max-width: 767px) {
  .container { width: calc(100% - 40px); }
  .site-header { height: 68px; justify-content: space-between; gap: 16px; }
  .wordmark { font-size: 22px; }
  .desktop-nav { display: none; }
  .mobile-menu { display: block; }
  .header-tools { gap: 10px; }
  .hero-actions { gap: 24px; }
  .example-panel { grid-template-columns: 1fr; }
  .workbench-bar { padding-inline: 18px; }
  .example-tabs button { font-size: 12px; }
  .workbench-hint { display: none; }
  .example-source .code-block pre { height: auto; max-height: 300px; min-height: 210px; padding: 20px; font-size: 12px; }
  .source-label { padding-inline: 20px; }
  .card-preview { border-left: 0; border-top: 1px solid var(--af-line); padding: 18px 26px 10px; }
  .example-workbench .card-preview { order: -1; border-top: 0; border-bottom: 1px solid var(--af-line); }
  .flashcard, .flashcard-inner { min-height: 195px; }
  .card-word { font-size: 44px; }
  .section { padding-block: 55px; }
  .identity-section, .start-section { grid-template-columns: 1fr; gap: 28px; }
  .section-copy p { max-width: 55ch; }
  .features { grid-template-columns: 1fr; gap: 37px; padding-block: 16px 50px; }
  .feature { gap: 14px; }
  .feature p { max-width: 55ch; }
  .post-grid { grid-template-columns: 1fr; gap: 30px; }
  .post-card h3 { font-size: 22px; }
  .blog-section { padding-bottom: 50px; }
  .site-footer { flex-direction: column; align-items: flex-start; gap: 17px; }
  .page-intro { padding-block: 40px 34px; }
  .page-intro p { font-size: 16px; }
  .example-detail { padding-block: 32px; }
  .example-detail .example-source .code-block pre { min-height: 0; }
  .article-header { padding-top: 35px; }
  .article-header .lede { font-size: 18px; }
  .prose h2 { font-size: 26px; }
  .prose pre { padding: 16px; }
}
@media (max-width: 374px) {
  .container { width: calc(100% - 32px); }
  .wordmark { font-size: 20px; gap: 6px; }
  .identity-controls { flex-direction: column; align-items: flex-start; gap: 0; }
  .identity-controls p { max-width: none; }
  .card-preview { padding-inline: 18px; }
}

/* Keep all shared tools operable at 320px and at increased text sizes. */
.site-header { flex-wrap: wrap; min-height: 76px; height: auto; padding-block: 12px; }
.header-tools { position: relative; margin-left: auto; flex-shrink: 0; min-width: 0; max-width: 100%; flex-wrap: wrap; justify-content: flex-end; }
.mobile-menu summary { white-space: nowrap; }
.mobile-menu nav a { white-space: normal; overflow-wrap: anywhere; }
@media (max-width: 767px) {
  .site-header { column-gap: 10px; row-gap: 8px; }
  .header-tools { gap: 8px; }
  .mobile-menu nav { top: 100%; right: 0; max-width: 100%; }
}
@media (max-width: 420px) {
  .site-header .wordmark > span:last-child { display: none; }
  .site-header .wordmark { gap: 0; }
}

